std::vector<std::string> names = {"Alice", "Bob", "Charlie"};

// Create an output iterator for strings, separated by commas
std::ostream_iterator<std::string> separator(std::cout, ", ");

// Write container contents directly to stdout
std::copy(names.begin(), names.end(), separator);

// Alternative: write a simple range to a stream (no delimiter needed)
std::vector<int> scores = {10, 20, 30};
std::ostream_iterator<int> plain_out(std::cout);

std::copy(scores.begin(), scores.end(), plain_out);
// Result: 102030
